Q: Split a string by whitespace, keeping quoted segments, allowing escaped quotes A: <p>Orignally I posted a comment asking if this could be done without a regex and just a single for() loop instead. But I decided to write it and it came out like this. It's an <strong>awful</strong> lot of code!</p>
<pre><code>//
// Split a string whilst allowing for quoted sections.
//
// @param  str   string  The string to Split
// @param  split string  The character to split on (default=,)
// @param  quote string  The quote character - either a single or double
//                       quote (default=&quot;)
// @param  empty boolean Whether to keep empty elements or not (default=true)
// @return       array  The resulting array
//
function splitzies (str, split = ',', quote = '&quot;', empty = true)
{
    // Loop over the string, character-by-character
    var ret = [], quoted = false, buf = '';

    for (var i=0; i&lt;str.length; ++i) {

        var chr  = str[i];
        var prev = i === 0 ? '' : str[i-1];
        var next = i === (str.length - 1) ? '' : str[i+1];

        // First - if this character is a backslash add the
        // next character no matter what it is
        if (chr === &quot;\\&quot;) {
            buf += next;
            i++;
            continue;
        }

        // Encountered the split char
        if (chr === split &amp;&amp; !quoted) {
            // Add the buffer to the return array if the buffer isn't
            // empty or empty elements are being kept (the default)
            if (buf.trim() || empty) {
                ret.push(buf);
                buf = '';
            }
            continue;
        }

        // Quote character
        if (chr === quote) {

            // Opening quote...
            if (!quoted) {
                quoted = true;
                continue;

            // Closing quote...
            } else {
                quoted = false;
                continue;
            }
        }

        buf += chr;
    }

     // Add the last bit to the returned array
     if (buf.trim() || empty) {
        ret.push(buf);
        buf = '';
     }

     return ret;
}

console.log(splitzies('Alf,Bert,Charlie'));
console.log(splitzies('Alf,  Bert ,   Charlie  '));
console.log(splitzies('Alf, Bert, Charlie','|'));
console.log(splitzies('Alf,Bert,&quot;Charlie G&quot;'));
console.log(splitzies('Alf      Bert   &quot;Charlie G&quot;', ' ', '&quot;', false));
console.log(splitzies('Alf,Bert,\\&quot;Charlie G\\&quot;'));
console.log(splitzies('Alf,Bert,Charlie|Doug|Eddie|Frank','|'));
console.log(splitzies('Alf,Bert,Charlie,&quot;Flugel, Horn&quot;'));
console.log(splitzies('Alf, Bert, Charlie,&quot;Doug,,, Eddie&quot;'));
console.log(splitzies(&quot;Alf,,,'Bert, Charlie'&quot;, ',', &quot;'&quot;, false));
console.log(splitzies(&quot;Alf,,,,'Bert,Charlie'&quot;, ',', &quot;'&quot;));
console.log(splitzies('pop rock &quot;hard rock&quot; &quot;\\&quot;dream\\&quot; pop&quot;',' '));
</code></pre>
